selector_to_html = {"a[href=\"#development-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Development Environment<a class=\"headerlink\" href=\"#development-environment\" title=\"Link to this heading\">#</a></h2><p>This project requires Python 3.11 or newer.  To set up your\ndevelopment environment on Linux or macOS, run these\n<a class=\"reference external\" href=\"https://www.gnu.org/software/make/\">GNU Make</a> commands from the\nproject root directory.</p>", "a[href=\"git/conventional.html#term-build\"]": "<dt id=\"term-build\"><code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code></dt><dd><p>a change to the build system or external dependencies, e.g., the\nmakefile</p></dd>", "a[href=\"#contribution-guidelines\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Contribution Guidelines<a class=\"headerlink\" href=\"#contribution-guidelines\" title=\"Link to this heading\">#</a></h1><p>This project combines\n<a class=\"reference external\" href=\"https://www.aleksandrhovhannisyan.com/blog/atomic-git-commits/\">atomic commits</a>,\na <a class=\"reference external\" href=\"https://archive.is/VpWTs\">linear commit history</a>, and the\n<a class=\"reference external\" href=\"https://www.atlassian.com/git/tutorials/comparing-workflows/feature-branch-workflow\">Git feature branch workflow</a>.\nPlease rebase changes on the latest HEAD of the main branch before\nsubmitting them for review as a\n<a class=\"reference external\" href=\"https://docs.github.com/en/pull-requests/collaborating-with-pull-requests\">GitHub pull request</a>.</p>", "a[href=\"#code-style\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Code Style<a class=\"headerlink\" href=\"#code-style\" title=\"Link to this heading\">#</a></h2><p>This project follows these code styles:</p>", "a[href=\"git/conventional.html#term-style\"]": "<dt id=\"term-style\"><code class=\"docutils literal notranslate\"><span class=\"pre\">style</span></code></dt><dd><p>a change that only affects formatting, or a change related to the\nlinter configuration</p></dd>", "a[href=\"git/conventional.html#term-ci\"]": "<dt id=\"term-ci\"><code class=\"docutils literal notranslate\"><span class=\"pre\">ci</span></code></dt><dd><p>a change to continuous integration/continuous delivery (CI/CD)\nprocesses, e.g., GitHub Actions</p></dd>", "a[href=\"git/conventional.html#term-fix\"]": "<dt id=\"term-fix\"><code class=\"docutils literal notranslate\"><span class=\"pre\">fix</span></code></dt><dd><p>a bug fix</p></dd>", "a[href=\"#commit-messages\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Messages<a class=\"headerlink\" href=\"#commit-messages\" title=\"Link to this heading\">#</a></h2><p>This project implements\n<a class=\"reference external\" href=\"https://semver.org/spec/v2.0.0.html\">Semantic Versioning 2.0.0</a> using\n<a class=\"reference external\" href=\"https://www.conventionalcommits.org/en/v1.0.0/\">Conventional Commits 1.0.0</a>:</p>", "a[href=\"#commit-scopes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Scopes<a class=\"headerlink\" href=\"#commit-scopes\" title=\"Link to this heading\">#</a></h3><p>An atomic commit can alter multiple files.  For example, an interface\nchange would require modifications the class definitions, method\ncalls, and property references throughout the codebase.  Per\n<em>Conventional Commits</em>, a commit scope is an <strong>OPTIONAL</strong>\nabbreviation, acronym, codename, or keyword that provides additional\ncontext to reviewers by naming the essential component of the change.</p><p>No commit scopes are currently in use.</p>", "a[href=\"git/conventional.html#term-chore\"]": "<dt id=\"term-chore\"><code class=\"docutils literal notranslate\"><span class=\"pre\">chore</span></code></dt><dd><p>a miscellaneous tooling or tool configuration change, e.g., the\n.gitignore file, or a change not covered by the other commit types</p></dd>", "a[href=\"git/conventional.html#term-docs\"]": "<dt id=\"term-docs\"><code class=\"docutils literal notranslate\"><span class=\"pre\">docs</span></code></dt><dd><p>a documentation-only change, including edits to example code,\nin-line documentation, and comments</p></dd>", "a[href=\"git/conventional.html#term-feat\"]": "<dt id=\"term-feat\"><code class=\"docutils literal notranslate\"><span class=\"pre\">feat</span></code></dt><dd><p>a new feature</p></dd>", "a[href=\"#commit-types\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Types<a class=\"headerlink\" href=\"#commit-types\" title=\"Link to this heading\">#</a></h3>", "a[href=\"git/conventional.html#term-refactor\"]": "<dt id=\"term-refactor\"><code class=\"docutils literal notranslate\"><span class=\"pre\">refactor</span></code></dt><dd><p>a code change that neither fixes a bug nor adds a feature</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
